(function(){
  var SH = Java.loadClass('net.neoforged.neoforge.server.ServerLifecycleHooks');
  var s = SH.getCurrentServer();
  if (s === null) { return { ok: false, reason: 'no-server' }; }
  var pl = s.getPlayerList().getPlayers();
  var src = (pl.size() > 0) ? pl.get(0).createCommandSourceStack() : s.createCommandSourceStack();
  var cmd = "/gamemode creative";
  s.getCommands().performPrefixedCommand(src, cmd);
  return { ok: true, cmd: cmd };
})()

(function(){
  var IC = Java.loadClass('com.mojang.blaze3d.platform.InputConstants');
  var KM = Java.loadClass('net.minecraft.client.KeyMapping');
  var k = IC.Type.KEYSYM.getOrCreate(69);
  KM.click(k);
  return { ok: true, keysym: 69 };
})()

(function(){
  var MC = Java.loadClass('net.minecraft.client.Minecraft');
  var mc = MC.getInstance();
  if (mc.screen === null) { return { ok: false, reason: 'no-screen' }; }
  var w = mc.getWindow().getGuiScaledWidth();
  var h = mc.getWindow().getGuiScaledHeight();
  var consumed = mc.screen.mouseClicked(w / 2, h / 2, 0);
  return { ok: true, button: 0, consumed: !!consumed };
})()

